import 'dart:convert';

import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'package:app/domain/entities/dish_info.dart';

/// Loads the bundled dish catalog (macros + ingredients + servings).
/// One JSON asset keeps the model labels and nutrition data in sync
/// (generated by ml/scripts/build_dish_catalog.py).
final dishCatalogProvider = FutureProvider<DishCatalog>((ref) async {
  final raw = await rootBundle.loadString(
    'assets/nutrition/khana_catalog.json',
  );
  return DishCatalog.fromJson(jsonDecode(raw) as Map<String, dynamic>);
});

/// How many classes the bundled catalog holds.
///
/// The dish count in the UI copy used to be hard-coded ("80 Indian
/// dishes") and went stale the moment the class set changed. It is
/// read from the catalog instead.
final dishCountProvider = Provider<int>((ref) {
  final catalog = ref.watch(dishCatalogProvider).valueOrNull;
  return catalog?.classes.length ?? 0;
});
